from payments import gateway, service


def _idempotency_keys(headers):
    """Return the Idempotency-Key values sent, with surrounding whitespace removed.

    Header names are matched case-insensitively, as HTTP requires. A blank value counts
    as no key, so the request is handled as it is without the header.
    """
    return [
        str(value or "").strip()
        for name, value in (headers or {}).items()
        if name.lower() == "idempotency-key"
    ]


def handle_post(conn, request):
    """POST /payments. The body is {"customer_id": int, "cents": int}.

    Optional header Idempotency-Key: see service.create_payment. Body validation runs
    first, so a malformed request gets 400 whatever its key, and it stores nothing.
    """
    body = request.get("body") or {}
    customer_id, cents = body.get("customer_id"), body.get("cents")
    if type(customer_id) is not int or type(cents) is not int or cents <= 0:
        return 400, {"error": "customer_id and a positive cents are required"}
    keys = _idempotency_keys(request.get("headers"))
    if len(keys) > 1:
        return 400, {"error": "Idempotency-Key sent more than once"}
    key = keys[0] if keys and keys[0] else None
    try:
        payment = service.create_payment(conn, customer_id, cents, key)
    except service.UnknownCustomer:
        return 404, {"error": "no such customer"}
    except service.KeyReused:
        return 409, {"error": "idempotency key reused"}
    except gateway.Declined as e:
        return 402, {"error": f"declined: {e}"}
    return 201, payment

