import sqlite3

from payments import gateway


class UnknownCustomer(Exception):
    pass


class KeyReused(Exception):
    """The idempotency key belongs to a payment for a different customer or amount."""


def _find_payment(conn, idempotency_key):
    if idempotency_key is None:
        return None
    row = conn.execute(
        "SELECT id, customer_id, cents, charge_id FROM payments WHERE idempotency_key = ?",
        (idempotency_key,),
    ).fetchone()
    return None if row is None else dict(row)


def _charge_and_record(conn, customer_id, cents, idempotency_key):
    """Charge and insert the payment row. The caller owns the transaction and commits."""
    if conn.execute("SELECT 1 FROM customers WHERE id = ?", (customer_id,)).fetchone() is None:
        raise UnknownCustomer(customer_id)
    charge_id = gateway.charge(conn, cents)
    cur = conn.execute(
        "INSERT INTO payments (customer_id, cents, charge_id, idempotency_key) VALUES (?, ?, ?, ?)",
        (customer_id, cents, charge_id, idempotency_key),
    )
    return {"id": cur.lastrowid, "customer_id": customer_id, "cents": cents, "charge_id": charge_id}


def create_payment(conn, customer_id, cents, idempotency_key=None):
    """Charge the customer and record the payment; return it as a dict.

    With an idempotency_key, a payment already stored under that key is returned
    unchanged when customer_id and cents match, and KeyReused is raised when they
    do not. Keys are matched across all customers, not per customer.

    Only successful payments are stored, so a declined or refused request leaves
    no trace under its key and a later request with that key is processed as new.

    The lookup, the charge and the insert run in one BEGIN IMMEDIATE transaction.
    That takes the write lock before the lookup, so two requests with the same key
    cannot both miss and both charge. The connection must have no open transaction.
    Every path ends with a commit or a rollback. A rollback also removes the
    gateway_log row of a charge that was made but not stored.
    """
    # With the default isolation_level, sqlite3 only issues its own BEGIN before DML when
    # no transaction is open. Issuing BEGIN IMMEDIATE first means it does not begin a second one.
    conn.execute("BEGIN IMMEDIATE")
    try:
        earlier = _find_payment(conn, idempotency_key)
        if earlier is None:
            try:
                payment = _charge_and_record(conn, customer_id, cents, idempotency_key)
            except sqlite3.IntegrityError:
                # Only the unique index on idempotency_key can fail here, and the lock
                # should prevent it. If it happens, undo this charge and replay the stored payment.
                conn.rollback()
                earlier = _find_payment(conn, idempotency_key)
                if earlier is None:
                    raise
            else:
                conn.commit()
                return payment
        conn.rollback()  # replay path: nothing was written
    except BaseException:
        conn.rollback()
        raise
    if (earlier["customer_id"], earlier["cents"]) != (customer_id, cents):
        raise KeyReused(idempotency_key)
    return earlier

