"""Migrate a v2 export to the v3 format.

migrate(src, accounts, dst) reads the v2 export at src (docs/FORMAT_V2.md) and the accounts file at accounts
(data/accounts.json shows the shape), writes the v3 file at dst (docs/FORMAT_V3.md, "Migrating from v2") and
returns the number of records written.

The export is streamed, never held whole. Output must be ordered by account, posted_at, id, and each id must
appear once, so the work is done as external sorts in a scratch directory (TMPDIR):

1. every line is read, checked and converted; the converted lines are sorted by (id, rev, line number) in
   sorted runs on disk;
2. merging those runs yields each id's entries together, lowest revision first, so the last one per id is the
   current revision;
3. the current revisions are sorted by (account, posted_at, id) and written to dst.

dst is not created until every line has been converted, so a MigrationError leaves no file behind.
"""
import heapq
import itertools
import json
import os
import pickle
import tempfile

from . import kinds, money, timefmt, v2, v3
from .accounts import load as load_accounts
from .errors import FormatError, MigrationError

CHUNK = 200_000  # records sorted in memory at a time
FAN_IN = 64  # sorted runs merged at a time, which keeps the number of open files small
BACKLOG_YEAR = 2020  # the bulk importer's times are account-local and have no offset (docs/FORMAT_V2.md)


def migrate(src, accounts, dst):
    held = load_accounts(accounts)
    with tempfile.TemporaryDirectory(prefix="ledger_v3_") as scratch:
        runs = _Scratch(scratch)
        by_id = runs.sorted(_converted(src, held))
        ordered = runs.sorted(_output_order(_current(by_id)))
        return _write(dst, ordered)


def _converted(src, held):
    """Every non-blank line of the export as a tuple (id, rev, line, account, type, amount_minor, currency,
    posted_at, memo), in file order. MigrationError for the first line that can't be migrated."""
    with open(src, "rb") as f:
        for number, raw in enumerate(f, 1):
            try:
                text = raw.decode("utf-8")
            except UnicodeDecodeError:
                raise MigrationError("not UTF-8", number) from None
            if not text.strip():
                continue
            try:
                rec = json.loads(text)
            except ValueError as e:
                raise MigrationError(f"not JSON ({e})", number) from None
            try:
                v2.check(rec, None)
            except FormatError as e:
                raise MigrationError(str(e), number) from None
            yield _convert(rec, held, number)


def _convert(rec, held, line):
    account = held.get(rec["account"])
    if account is None:
        raise MigrationError(f"account {rec['account']!r} is not in the accounts file", line)

    kind = kinds.LEGACY.get(rec["kind"], rec["kind"])
    if kind not in kinds.TYPES:
        raise MigrationError(f"unknown kind {rec['kind']!r}", line)

    amount = rec["amount"]
    if amount.startswith("-"):
        raise MigrationError(f"amount {amount!r} is negative, but v2 amounts are positive", line)
    currency = account.currency if rec["currency"] is None else rec["currency"]
    if not money.is_currency(currency):
        raise MigrationError(f"bad currency {currency!r}", line)
    try:
        minor = money.to_minor(amount, currency)
    except ValueError as e:
        raise MigrationError(str(e), line) from None

    try:
        stamp = timefmt.parse_ts(rec["ts"])
    except ValueError as e:
        raise MigrationError(str(e), line) from None
    if stamp.tzinfo is None:
        # Only the 2020 backlog writes times without an offset; they are the account's local time.
        if stamp.year != BACKLOG_YEAR:
            raise MigrationError(f"ts {rec['ts']!r} has no UTC offset, and only {BACKLOG_YEAR} backlog times "
                                 f"are account-local", line)
        stamp = stamp.replace(tzinfo=account.tz)
    try:
        posted_at = timefmt.to_utc_z(stamp)
    except (ValueError, OverflowError) as e:
        raise MigrationError(f"ts {rec['ts']!r}: {e}", line) from None

    record = {"id": rec["id"], "account": rec["account"], "type": kind, "amount_minor": minor * kinds.SIGN[kind],
              "currency": currency, "posted_at": posted_at, "memo": rec["memo"], "source_rev": rec["rev"]}
    try:
        v3.validate(record)
    except FormatError as e:
        raise MigrationError(str(e), line) from None
    for field in ("id", "account", "memo"):
        try:
            record[field].encode("utf-8")
        except UnicodeEncodeError:
            raise MigrationError(f"{field} is not valid Unicode text", line) from None

    return (record["id"], rec["rev"], line, record["account"], kind, record["amount_minor"], currency, posted_at,
            record["memo"])


def _current(by_id):
    """The current revision of each id: the last of its entries in (rev, line) order."""
    best = None
    for entry in by_id:
        if best is not None and entry[0] != best[0]:
            yield best
        best = entry
    if best is not None:
        yield best


def _output_order(current):
    for id_, rev, line, account, kind, amount_minor, currency, posted_at, memo in current:
        yield (account, posted_at, id_, kind, amount_minor, currency, memo, rev)


def _write(dst, ordered):
    count = 0
    with open(dst, "w", encoding="utf-8", newline="\n") as f:
        for account, posted_at, id_, kind, amount_minor, currency, memo, rev in ordered:
            f.write(v3.dump_line({"id": id_, "account": account, "type": kind, "amount_minor": amount_minor,
                                  "currency": currency, "posted_at": posted_at, "memo": memo,
                                  "source_rev": rev}))
            count += 1
    return count


class _Scratch:
    """Sorts a stream that may be far bigger than memory, using sorted runs in a scratch directory."""

    def __init__(self, directory):
        self.directory = directory
        self.names = itertools.count()

    def _path(self):
        return os.path.join(self.directory, f"run{next(self.names)}")

    def sorted(self, items):
        """The items in ascending order, as an iterator. Call only after the input is fully read."""
        runs, chunk = [], []
        for item in items:
            chunk.append(item)
            if len(chunk) == CHUNK:
                runs.append(self._spill(chunk))
                chunk = []
        if chunk:
            runs.append(self._spill(chunk))
        while len(runs) > FAN_IN:
            merged = []
            for i in range(0, len(runs), FAN_IN):
                group = runs[i:i + FAN_IN]
                path = self._path()
                with open(path, "wb") as f:
                    for item in heapq.merge(*(_read_run(p) for p in group)):
                        pickle.dump(item, f, protocol=pickle.HIGHEST_PROTOCOL)
                for p in group:
                    os.remove(p)
                merged.append(path)
            runs = merged
        return heapq.merge(*(_read_run(p) for p in runs))

    def _spill(self, chunk):
        chunk.sort()
        path = self._path()
        with open(path, "wb") as f:
            for item in chunk:
                pickle.dump(item, f, protocol=pickle.HIGHEST_PROTOCOL)
        return path


def _read_run(path):
    with open(path, "rb") as f:
        while True:
            try:
                yield pickle.load(f)
            except EOFError:
                return

