from billing import rules


def balances(conn) -> dict[int, int]:
    """Each account's balance in cents, {account_id: cents}: what its invoices that aren't voided ask for, minus the payments on them that rules.counts accepts. Every account is in the result, 0 when it has nothing to pay."""
    account_ids = [account_id for (account_id,) in conn.execute("SELECT id FROM accounts").fetchall()]
    # Accepted payments on non-voided invoices, grouped by invoice id (rules.counts decides which).
    accepted = {}
    for invoice_id, paid, status, method in conn.execute(
            "SELECT p.invoice_id, p.amount_cents, p.status, p.method FROM payments p "
            "JOIN invoices i ON i.id = p.invoice_id WHERE i.voided = 0 ORDER BY p.invoice_id, p.id").fetchall():
        if rules.counts(status, method):
            accepted.setdefault(invoice_id, []).append(paid)
    # Invoices in (account, id) order, the order the per-account queries visited them in.
    owed = {}
    for account_id, invoice_id, cents in conn.execute(
            "SELECT account_id, id, amount_cents FROM invoices WHERE voided = 0 ORDER BY account_id, id").fetchall():
        owed.setdefault(account_id, 0)
        owed[account_id] += cents
        for paid in accepted.get(invoice_id, ()):
            owed[account_id] -= paid
    return {account_id: owed.get(account_id, 0) for account_id in account_ids}

from billing import rules


def balances(conn) -> dict[int, int]:
    """Each account's balance in cents, {account_id: cents}: what its invoices that aren't voided ask for, minus the payments on them that rules.counts accepts. Every account is in the result, 0 when it has nothing to pay."""
    # Three statements total. Rows are fetched in the same order the old per-account /
    # per-invoice queries returned them (index order: account_id/invoice_id, then rowid),
    # and the running total is accumulated in the same interleaved order, so the
    # result (including any non-integer amounts) is identical.
    payments_by_invoice = {}
    for invoice_id, paid, status, method in conn.execute(
            "SELECT p.invoice_id, p.amount_cents, p.status, p.method"
            " FROM payments p JOIN invoices i ON i.id = p.invoice_id"
            " WHERE i.voided = 0 ORDER BY p.invoice_id, p.id"):
        payments_by_invoice.setdefault(invoice_id, []).append((paid, status, method))

    invoices_by_account = {}
    for invoice_id, account_id, cents in conn.execute(
            "SELECT id, account_id, amount_cents FROM invoices WHERE voided = 0 ORDER BY account_id, id"):
        invoices_by_account.setdefault(account_id, []).append((invoice_id, cents))

    result = {}
    for (account_id,) in conn.execute("SELECT id FROM accounts").fetchall():
        owed = 0
        for invoice_id, cents in invoices_by_account.get(account_id, ()):
            owed += cents
            for paid, status, method in payments_by_invoice.get(invoice_id, ()):
                if rules.counts(status, method):
                    owed -= paid
        result[account_id] = owed
    return result

