import sqlite3

from payments import gateway, service

KEY_REUSED = {"error": "idempotency key reused"}


def _header(request, name):
    """Return the value of header name, matched case-insensitively, or None."""
    name = name.lower()
    for key, value in (request.get("headers") or {}).items():
        if key.lower() == name:
            return value
    return None


def _replay(earlier, customer_id, cents):
    """The response for a request whose key matches the earlier payment."""
    if (earlier["customer_id"], earlier["cents"]) != (customer_id, cents):
        return 409, KEY_REUSED
    return 201, earlier


def handle_post(conn, request):
    """POST /payments. The body is {"customer_id": int, "cents": int}.

    With an Idempotency-Key header, a repeat of an earlier successful request gets
    the earlier response back without a new charge, and a key reused with a
    different body gets 409. Only successful payments store their key.
    """
    body = request.get("body") or {}
    customer_id, cents = body.get("customer_id"), body.get("cents")
    if type(customer_id) is not int or type(cents) is not int or cents <= 0:
        return 400, {"error": "customer_id and a positive cents are required"}
    key = _header(request, "Idempotency-Key")
    if key is not None:
        # Take the write lock before looking the key up, so a concurrent request with
        # the same key (on any worker) waits here until this one commits or rolls
        # back, and then finds the payment instead of charging the card again.
        if not conn.in_transaction:
            conn.execute("BEGIN IMMEDIATE")
        earlier = service.find_by_idempotency_key(conn, key)
        if earlier is not None:
            conn.rollback()
            return _replay(earlier, customer_id, cents)
    try:
        payment = service.create_payment(conn, customer_id, cents, key)
    except service.UnknownCustomer:
        conn.rollback()
        return 404, {"error": "no such customer"}
    except gateway.Declined as e:
        conn.rollback()
        return 402, {"error": f"declined: {e}"}
    except sqlite3.IntegrityError:
        # Backstop: another request stored the same key first. Rolling back undoes
        # this request's payment row and gateway_log entry together.
        conn.rollback()
        earlier = service.find_by_idempotency_key(conn, key) if key is not None else None
        if earlier is None:
            raise
        return _replay(earlier, customer_id, cents)
    return 201, payment

