import sqlite3

from payments import gateway


class UnknownCustomer(Exception):
    pass


class KeyReused(Exception):
    pass


def create_payment(conn, customer_id, cents, idempotency_key=None):
    """Charge the customer and record the payment; return it as a dict.

    With an idempotency_key, a payment already stored under that key is returned
    as it was if customer and cents match; otherwise KeyReused is raised. Either way
    nothing is charged for a repeated key."""
    if idempotency_key is None:
        return _charge_and_record(conn, customer_id, cents, None)
    # BEGIN IMMEDIATE takes the write lock now, so a concurrent retry on another
    # worker waits here and then sees the payment this one stores.
    conn.execute("BEGIN IMMEDIATE")
    try:
        stored = _find_by_key(conn, idempotency_key)
        if stored is None:
            return _charge_and_record(conn, customer_id, cents, idempotency_key)
    except sqlite3.IntegrityError:
        # Only if another writer stored this key after our lookup. Use its payment,
        # unless the error had some other cause.
        conn.rollback()
        stored = _find_by_key(conn, idempotency_key)
        if stored is None:
            raise
    except BaseException:
        conn.rollback()
        raise
    conn.rollback()
    return _replay(stored, customer_id, cents)


def _find_by_key(conn, idempotency_key):
    return conn.execute("SELECT id, customer_id, cents, charge_id FROM payments WHERE idempotency_key = ?",
                        (idempotency_key,)).fetchone()


def _replay(stored, customer_id, cents):
    payment_id, stored_customer_id, stored_cents, charge_id = stored
    if (stored_customer_id, stored_cents) != (customer_id, cents):
        raise KeyReused(payment_id)
    return {"id": payment_id, "customer_id": stored_customer_id, "cents": stored_cents, "charge_id": charge_id}


def _charge_and_record(conn, customer_id, cents, idempotency_key):
    if conn.execute("SELECT 1 FROM customers WHERE id = ?", (customer_id,)).fetchone() is None:
        raise UnknownCustomer(customer_id)
    charge_id = gateway.charge(conn, cents)
    cur = conn.execute("INSERT INTO payments (customer_id, cents, charge_id, idempotency_key) VALUES (?, ?, ?, ?)",
                       (customer_id, cents, charge_id, idempotency_key))
    conn.commit()
    return {"id": cur.lastrowid, "customer_id": customer_id, "cents": cents, "charge_id": charge_id}

files.archive/extract.py:
"""Unpacking a tar archive into a folder without letting it reach outside that folder.

Archives reach us from two places, plugin bundles (plugins/installer.py) and user backups (backups/restore.py), and
neither is trusted. safe_extract checks every member before it writes anything, so an archive it refuses leaves
the destination as it was.

The check can't look at member names alone: a link earlier in the archive changes where later names lead
("d/l -> .." makes "d/l/x" land in the root, not in d/l). So the plan builds the tree the archive will make, links
included, and resolves every path through it the way the kernel will, one component at a time. Each member is then
written to the physical path it resolved to, which has no links in it.
"""
import os
import shutil
import stat
import tarfile

from . import limits, paths
from .errors import UnsafeArchive

FILE_MODE = 0o644
EXEC_MODE = 0o755
MAX_LINK_HOPS = 40  # as many as Linux follows before ELOOP

DIR, FILE, LINK, OTHER = "dir", "file", "link", "other"


def safe_extract(tar_path, dest):
    """Extract the tar at tar_path into the existing folder dest; return the member names, in archive order.

    Regular files, folders and symbolic links are extracted, and a link may point only inside dest. A member that
    would land outside dest, a link that points outside it, a name listed twice, any other kind of member or an
    archive over the size limits raises UnsafeArchive, and then nothing has been written."""
    root = os.path.realpath(dest)
    if not os.path.isdir(root):
        raise NotADirectoryError(dest)
    try:
        with tarfile.open(tar_path) as tar:
            members = tar.getmembers()
            limits.check(members)
            plan = plan_members(root, members)
            write_all(tar, root, plan)
    except tarfile.TarError as e:
        raise UnsafeArchive(f"not a readable tar archive: {e}") from None
    return [paths.clean_name(m.name) for m in members]


class Tree:
    """The destination as it will be once the archive is extracted: what is already on disk under root, with the
    archive's members laid over it. Paths are tuples of physical components under root (no links in them)."""

    def __init__(self, root):
        self.root = root
        self.nodes = {(): (DIR, None)}

    def lookup(self, parts):
        if parts in self.nodes:
            return self.nodes[parts]
        try:
            st = os.lstat(paths.under(self.root, "/".join(parts)))
        except FileNotFoundError:
            return None
        except NotADirectoryError:
            return None
        if stat.S_ISLNK(st.st_mode):
            node = (LINK, os.readlink(paths.under(self.root, "/".join(parts))))
        elif stat.S_ISDIR(st.st_mode):
            node = (DIR, None)
        elif stat.S_ISREG(st.st_mode):
            node = (FILE, None)
        else:
            node = (OTHER, None)
        self.nodes[parts] = node
        return node

    def resolve(self, base, components, what, creating):
        """The physical path base/components leads to, following links like the kernel does. UnsafeArchive if
        any step of the way leaves root. With creating, the path is one we are about to write under: every
        missing component becomes a folder, and a loop or a file in the way is refused."""
        cur = list(base)
        pending = [c for c in components if c not in ("", ".")]
        hops = 0
        while pending:
            part = pending.pop(0)
            if part == "..":
                if not cur:
                    raise UnsafeArchive(f"{what} leads outside the destination")
                cur.pop()
                continue
            cand = tuple(cur) + (part,)
            node = self.lookup(cand)
            if node is None:
                if creating:
                    self.nodes[cand] = (DIR, None)
            elif node[0] == LINK:
                hops += 1
                if hops > MAX_LINK_HOPS:
                    if creating:
                        raise UnsafeArchive(f"{what} goes through a loop of links")
                    return tuple(cur)  # the kernel gives up with ELOOP; it never gets out
                target = node[1]
                if not target or target.startswith("/"):
                    raise UnsafeArchive(f"{what} goes through a link to an absolute path")
                pending = [c for c in target.split("/") if c not in ("", ".")] + pending
                continue
            elif node[0] != DIR:
                if creating:
                    raise UnsafeArchive(f"{what} goes through {'/'.join(cand)}, which isn't a folder")
                return tuple(cur)  # the kernel stops with ENOTDIR
            cur.append(part)
        return tuple(cur)


def plan_members(root, members):
    """[(member, the absolute path it goes to), ...] once every member has passed, or UnsafeArchive."""
    tree = Tree(root)
    seen = set()
    links = []
    plan = []
    for member in members:
        name = paths.clean_name(member.name)
        if name in seen:
            raise UnsafeArchive(f"{name} is listed twice")
        seen.add(name)
        if member.issym():
            if not member.linkname or os.path.isabs(member.linkname) or member.linkname.startswith("/"):
                raise UnsafeArchive(f"{name} links to an absolute path")
            if "\x00" in member.linkname:
                raise UnsafeArchive(f"{name} has a bad link target")
            if not paths.is_within(root, paths.link_target(root, name, member.linkname)):
                raise UnsafeArchive(f"{name} links to {member.linkname}, outside the destination")
        elif member.islnk():
            raise UnsafeArchive(f"{name} is a hard link")
        elif not (member.isfile() or member.isdir()):
            raise UnsafeArchive(f"{name} is a device, a FIFO or another special file")
        parts = name.split("/")
        parent = tree.resolve((), parts[:-1], name, creating=True)
        here = parent + (parts[-1],)
        existing = tree.lookup(here)
        if member.isdir():
            if existing is not None and existing[0] != DIR:
                raise UnsafeArchive(f"{name} would replace a {existing[0]} already at {'/'.join(here)}")
            tree.nodes[here] = (DIR, None)
        else:
            if existing is not None:
                raise UnsafeArchive(f"{name} would overwrite the {existing[0]} already at {'/'.join(here)}")
            if member.issym():
                tree.nodes[here] = (LINK, member.linkname)
                links.append((name, parent, member.linkname))
            else:
                tree.nodes[here] = (FILE, None)
        target = paths.under(root, "/".join(here))
        if not paths.is_within(root, target) or target == root:
            raise UnsafeArchive(f"{name} would be written outside the destination")
        plan.append((member, target))
    # Links may point at members later in the archive, so they are followed once the whole tree is known.
    for name, parent, linkname in links:
        tree.resolve(parent, linkname.split("/"), f"{name} -> {linkname}", creating=False)
    return plan


def write_all(tar, root, plan):
    """Write the planned members; if anything fails part way, remove what was written and re-raise."""
    created = []
    try:
        for member, target in plan:
            write_member(tar, root, member, target, created)
    except BaseException:
        for path in reversed(created):
            try:
                if os.path.isdir(path) and not os.path.islink(path):
                    os.rmdir(path)
                else:
                    os.unlink(path)
            except OSError:
                pass
        raise


def make_dirs(root, path, created):
    """Like os.makedirs(path, exist_ok=True) for a path under root with no links in it; records what it made."""
    rel = os.path.relpath(path, root)
    if rel == ".":
        return
    cur = root
    for part in rel.split(os.sep):
        cur = os.path.join(cur, part)
        try:
            os.mkdir(cur)
            created.append(cur)
        except FileExistsError:
            st = os.lstat(cur)
            if not stat.S_ISDIR(st.st_mode):
                raise UnsafeArchive(f"{os.path.relpath(cur, root)} changed under us: not a folder") from None


def write_member(tar, root, member, target, created):
    if member.isdir():
        make_dirs(root, target, created)
        return
    make_dirs(root, os.path.dirname(target), created)
    if member.issym():
        os.symlink(member.linkname, target)
        created.append(target)
        return
    mode = EXEC_MODE if member.mode & 0o100 else FILE_MODE
    fd = os.open(target, os.O_WRONLY | os.O_CREAT | os.O_EXCL | getattr(os, "O_NOFOLLOW", 0), FILE_MODE)
    created.append(target)
    with tar.extractfile(member) as src, os.fdopen(fd, "wb") as out:
        shutil.copyfileobj(src, out)
        os.fchmod(out.fileno(), mode)

