"""Make customers.email unique, ignoring ASCII case.

Customers whose emails are equal after trimming surrounding spaces and ignoring ASCII case are one person. Keep the
one with the earliest created_at (the lowest id on a tie), move every order and address of the others to it, and
delete the others. If the kept customer's name is NULL or empty, give it the name of the earliest-created duplicate
that has one. Store every customer's email trimmed, with ASCII letters lowercased; other characters stay as they are.

Afterwards the customers table declares email as `email TEXT NOT NULL COLLATE NOCASE UNIQUE`. Everything else in the
schema stays as it is: the same tables and columns, the foreign keys with ON DELETE CASCADE, the index and the view.
Every order and address survives. conn comes from store.db.connect, with foreign keys on and no open transaction;
leave foreign keys on, commit your work, and set user_version to 2.
"""

import re

_ASCII_LOWER = str.maketrans("ABCDEFGHIJKLMNOPQRSTUVWXYZ", "abcdefghijklmnopqrstuvwxyz")

_EMAIL_COLUMN = re.compile(r"\bemail\s+TEXT\s+NOT\s+NULL\b", re.IGNORECASE)
_TABLE_NAME = re.compile(r"^\s*CREATE\s+TABLE\s+\"?customers\"?", re.IGNORECASE)


def _normalize(email):
    # Trim surrounding spaces only and lowercase ASCII letters only.
    return email.strip(" ").translate(_ASCII_LOWER)


def _merge(conn):
    rows = conn.execute("SELECT id, email, name, created_at FROM customers ORDER BY created_at, id").fetchall()
    groups = {}
    for row in rows:
        groups.setdefault(_normalize(row[1]), []).append(row)

    for email, members in groups.items():
        kept_id, _, kept_name, _ = members[0]
        others = [m[0] for m in members[1:]]
        for other_id in others:
            conn.execute("UPDATE orders SET customer_id = ? WHERE customer_id = ?", (kept_id, other_id))
            conn.execute("UPDATE addresses SET customer_id = ? WHERE customer_id = ?", (kept_id, other_id))
        if kept_name is None or kept_name == "":
            for _, _, name, _ in members[1:]:
                if name is not None and name != "":
                    kept_name = name
                    break
        conn.execute("UPDATE customers SET email = ?, name = ? WHERE id = ?", (email, kept_name, kept_id))
        for other_id in others:
            conn.execute("DELETE FROM customers WHERE id = ?", (other_id,))


def _rebuild_customers(conn):
    (table_sql,) = conn.execute("SELECT sql FROM sqlite_master WHERE type = 'table' AND name = 'customers'").fetchone()
    new_sql, n = _EMAIL_COLUMN.subn("email TEXT NOT NULL COLLATE NOCASE UNIQUE", table_sql, count=1)
    if n != 1:
        raise RuntimeError("unexpected customers.email definition: %r" % table_sql)
    new_sql, n = _TABLE_NAME.subn("CREATE TABLE customers_new", new_sql, count=1)
    if n != 1:
        raise RuntimeError("unexpected customers table definition: %r" % table_sql)

    # Views that mention customers would make the rename fail while the table is missing; recreate them verbatim.
    views = conn.execute(
        "SELECT name, sql FROM sqlite_master WHERE type = 'view' AND sql IS NOT NULL ORDER BY rowid"
    ).fetchall()
    for name, _ in views:
        conn.execute('DROP VIEW "%s"' % name.replace('"', '""'))

    conn.execute(new_sql)
    conn.execute(
        "INSERT INTO customers_new (id, email, name, created_at) SELECT id, email, name, created_at FROM customers"
    )
    conn.execute("DROP TABLE customers")
    conn.execute("ALTER TABLE customers_new RENAME TO customers")

    for _, sql in views:
        conn.execute(sql)


def upgrade(conn):
    # Foreign keys must be off while the parent table is rebuilt (DROP TABLE would cascade to orders/addresses),
    # and this pragma only takes effect outside a transaction.
    conn.execute("PRAGMA foreign_keys = OFF")
    try:
        conn.execute("BEGIN")
        try:
            _merge(conn)
            _rebuild_customers(conn)
            if conn.execute("PRAGMA foreign_key_check").fetchall():
                raise RuntimeError("foreign key violations after merging customers")
            conn.execute("PRAGMA user_version = 2")
            conn.commit()
        except BaseException:
            conn.rollback()
            raise
    finally:
        conn.execute("PRAGMA foreign_keys = ON")

files.archive/extract.py:
"""Unpacking a tar archive into a folder without letting it reach outside that folder.

Archives reach us from two places, plugin bundles (plugins/installer.py) and user backups (backups/restore.py), and
neither is trusted. safe_extract works out, on a model of the destination, what every member would create and
where, refuses the archive if anything would land or point outside the destination, and only then writes.

The model follows links the way the kernel does, in archive order, so a member listed after a link is placed
where that link really leads (and refused if that is outside), and a link's target is judged by where it leads
once the whole archive is in place, not by how its text looks. Everything is written to a path that holds no
link, never through one.
"""
import lzma
import os
import shutil
import stat
import tarfile
import zlib

from . import limits, paths
from .errors import UnsafeArchive

FILE_MODE = 0o644
EXEC_MODE = 0o755
MAX_LINK_HOPS = 40  # like the kernel's limit on links followed in one lookup
MAX_LINKNAME = 4096

FILE, DIR, LINK, OTHER = "file", "folder", "link", "other"


class _Loop(Exception):
    """A path that runs into too many links (a cycle)."""


class _Model:
    """What the destination holds as the archive is laid down on it: what exists now, plus what the plan adds."""

    def __init__(self, root):
        self.root = root
        self.added = {}  # absolute path -> (kind, link text); entries the plan creates
        self.real = {}  # absolute path -> the same, or None, as found on disk before anything is written

    def lookup(self, path):
        node = self.added.get(path)
        if node is not None:
            return node
        if path not in self.real:
            try:
                st = os.lstat(path)
            except (FileNotFoundError, NotADirectoryError):
                self.real[path] = None
            except OSError as e:
                raise UnsafeArchive(f"can't inspect {path}: {e.strerror}") from None
            else:
                if stat.S_ISLNK(st.st_mode):
                    self.real[path] = (LINK, os.readlink(path))
                elif stat.S_ISDIR(st.st_mode):
                    self.real[path] = (DIR, None)
                elif stat.S_ISREG(st.st_mode):
                    self.real[path] = (FILE, None)
                else:
                    self.real[path] = (OTHER, None)
        return self.real[path]

    def resolve(self, start, parts, follow_last, name):
        """The absolute path that `parts`, taken from the folder `start`, leads to, following every link on the way
        (the last part too when follow_last). UnsafeArchive if the walk steps outside the root at any point; _Loop
        if it follows too many links. Parts that don't exist yet are taken as they are."""
        todo = list(reversed(parts))
        cur, hops = start, 0
        while todo:
            part = todo.pop()
            if part in ("", "."):
                continue
            if part == "..":
                if cur == self.root:
                    raise UnsafeArchive(f"{name} would reach outside the destination")
                cur = os.path.dirname(cur)
                continue
            nxt = os.path.join(cur, part)
            node = self.lookup(nxt)
            if node is not None and node[0] == LINK and (todo or follow_last):
                hops += 1
                if hops > MAX_LINK_HOPS:
                    raise _Loop(name)
                text = node[1]
                if not text or text.startswith("/"):
                    raise UnsafeArchive(f"{name} goes through a link to an absolute path")
                todo.extend(reversed(text.split("/")))
                continue
            cur = nxt
        if not paths.is_within(self.root, cur):
            raise UnsafeArchive(f"{name} would reach outside the destination")
        return cur

    def add(self, path, kind, text=None):
        self.added[path] = (kind, text)


def safe_extract(tar_path, dest):
    """Extract the tar at tar_path into the existing folder dest; return the member names, in archive order.

    Regular files, folders and symbolic links are extracted, and a link may point only inside dest. A member that
    would land outside dest, a link that points (or leads, through other links) outside it, a name listed twice,
    any other kind of member, a damaged archive or one over the size limits raises UnsafeArchive, and then nothing
    has been written (or, if something fails while writing, what was written is removed again)."""
    root = os.path.realpath(dest)
    if not os.path.isdir(root):
        raise NotADirectoryError(dest)
    try:
        with tarfile.open(tar_path) as tar:
            members = tar.getmembers()
            limits.check(members)
            ops = plan_members(root, members)
            execute(tar, root, ops)
    except (tarfile.TarError, EOFError, zlib.error, lzma.LZMAError) as e:
        raise UnsafeArchive(f"not a readable archive: {e}") from None
    return [paths.clean_name(m.name) for m in members]


def plan_members(root, members):
    """The writes, [(op, path, arg), ...], that lay the members down once every one has passed; UnsafeArchive if
    any would land or point outside root or can't be written. op is "mkdir", "file" (arg: the member) or "link"
    (arg: the link text); path is absolute and holds no link."""
    model = _Model(root)
    ops = []
    seen = set()
    links = []  # (name, folder it's in, link text), judged once everything is in place
    for member in members:
        name = paths.clean_name(member.name)
        if name in seen:
            raise UnsafeArchive(f"{name} is listed twice")
        seen.add(name)
        if member.issym():
            text = member.linkname
            if not text or text.startswith("/"):
                raise UnsafeArchive(f"{name} links to an absolute path")
            if "\x00" in text or "\\" in text or len(text.encode("utf-8", "surrogateescape")) > MAX_LINKNAME:
                raise UnsafeArchive(f"{name} has a bad link target")
            if len(text) > 1 and text[1] == ":":
                raise UnsafeArchive(f"{name} links to a drive path")
        elif member.islnk():
            raise UnsafeArchive(f"{name} is a hard link")
        elif not (member.isfile() or member.isdir()):
            raise UnsafeArchive(f"{name} is a device, a FIFO or another special file")

        parts = name.split("/")
        try:
            folder = model.resolve(root, parts[:-1], True, name)
            path = os.path.join(folder, parts[-1])
            # The folder must exist or be made, one folder at a time; nothing on the way may be a file.
            missing, here = [], root
            for part in os.path.relpath(folder, root).split(os.sep) if folder != root else []:
                here = os.path.join(here, part)
                node = model.lookup(here)
                if node is None:
                    missing.append(here)
                elif node[0] != DIR:
                    raise UnsafeArchive(f"{name} would go inside {here}, which isn't a folder")
        except _Loop:
            raise UnsafeArchive(f"{name} goes through a cycle of links") from None
        for d in missing:
            model.add(d, DIR)
            ops.append(("mkdir", d, None))
        existing = model.lookup(path)
        if member.isdir():
            if existing is None:
                model.add(path, DIR)
                ops.append(("mkdir", path, None))
            elif existing[0] != DIR:
                raise UnsafeArchive(f"{name} is already there as something other than a folder")
            continue
        if existing is not None:
            raise UnsafeArchive(f"{name} is listed twice or already exists")
        if member.issym():
            model.add(path, LINK, member.linkname)
            ops.append(("link", path, member.linkname))
            links.append((name, folder, member.linkname))
        else:
            model.add(path, FILE)
            ops.append(("file", path, member))

    # A link is judged where it leads in the finished tree, whatever the order the archive listed things in.
    for name, folder, text in links:
        try:
            model.resolve(folder, text.split("/"), True, name)
        except _Loop:
            pass  # a cycle leads nowhere, in or out
        except UnsafeArchive:
            raise UnsafeArchive(f"{name} links to {text}, outside the destination") from None
    return ops


def execute(tar, root, ops):
    created = []
    try:
        for op, path, arg in ops:
            write(tar, root, op, path, arg, created)
    except BaseException:
        rollback(created)
        raise


def write(tar, root, op, path, arg, created):
    parent = os.path.dirname(path)
    # What the plan assumed must still be true: nothing along the way has turned into a link.
    if os.path.realpath(parent) != parent or not paths.is_within(root, parent):
        raise UnsafeArchive(f"{path} no longer sits where it was planned")
    if op == "mkdir":
        os.mkdir(path)
        created.append(path)
    elif op == "link":
        os.symlink(arg, path)
        created.append(path)
    else:
        mode = EXEC_MODE if arg.mode & 0o100 else FILE_MODE
        fd = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW, 0o600)
        created.append(path)
        with os.fdopen(fd, "wb") as out, tar.extractfile(arg) as src:
            shutil.copyfileobj(src, out)
            if out.tell() != arg.size:
                raise UnsafeArchive(f"{arg.name} is cut short")
            os.fchmod(out.fileno(), mode)


def rollback(created):
    for path in reversed(created):
        try:
            if os.path.isdir(path) and not os.path.islink(path):
                os.rmdir(path)
            else:
                os.unlink(path)
        except OSError:
            pass


def write_marker(path, text):
    """Write an install or restore marker at path, a file the caller owns: whatever the archive left there (a
    file, a link, a folder) is replaced, and a link is never followed."""
    try:
        st = os.lstat(path)
    except FileNotFoundError:
        pass
    else:
        if stat.S_ISDIR(st.st_mode):
            shutil.rmtree(path)
        else:
            os.unlink(path)
    fd = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW, 0o644)
    with os.fdopen(fd, "w", encoding="utf-8") as f:
        f.write(text)

files.archive/paths.py:
"""Path rules for archive members. A member's name is a POSIX path relative to the archive's root."""
import os
import posixpath

from .errors import UnsafeArchive

MAX_NAME = 1024
MAX_PART = 255  # longest file name the filesystem takes


def clean_name(name):
    """The member name as a relative path with no empty or "." parts. UnsafeArchive for an absolute name, a drive
    letter, a ".." part, a backslash or a NUL."""
    if not isinstance(name, str) or not name or "\x00" in name or "\\" in name:
        raise UnsafeArchive(f"bad member name {name!r}")
    if name.startswith("/") or (len(name) > 1 and name[1] == ":"):
        raise UnsafeArchive(f"{name} is an absolute path")
    parts = [part for part in name.split("/") if part not in ("", ".")]
    if not parts:
        raise UnsafeArchive(f"bad member name {name!r}")
    if ".." in parts:
        raise UnsafeArchive(f"{name} climbs out with ..")
    if any(len(part.encode("utf-8", "surrogateescape")) > MAX_PART for part in parts):
        raise UnsafeArchive(f"a part of {name[:60]}... is longer than {MAX_PART} bytes")
    clean = "/".join(parts)
    if len(clean) > MAX_NAME:
        raise UnsafeArchive(f"a member name is longer than {MAX_NAME} characters")
    return clean


def is_within(root, path):
    """Whether path is root or under it; both absolute and normalized."""
    return path == root or path.startswith(root.rstrip(os.sep) + os.sep)


def under(root, name):
    """The absolute path a member name maps to under root."""
    return os.path.join(root, *name.split("/"))

files.backups/manifest.py:
"""MANIFEST.json, written at the root of every backup: the sha256 of each file and the target of each link."""
import hashlib
import json
import os

from archive.errors import UnsafeArchive
from archive.pack import walk
from archive.paths import clean_name, is_within

NAME = "MANIFEST.json"


class ManifestMismatch(ValueError):
    pass


def sha256(path):
    digest = hashlib.sha256()
    with open(path, "rb") as f:
        for block in iter(lambda: f.read(1 << 16), b""):
            digest.update(block)
    return digest.hexdigest()


def build(root):
    """{"files": {path: sha256}, "links": {path: target}} for the tree under root, paths relative and POSIX."""
    files, links = {}, {}
    for rel, path in walk(root):
        if rel == NAME:
            continue
        if os.path.islink(path):
            links[rel] = os.readlink(path)
        elif os.path.isfile(path):
            files[rel] = sha256(path)
    return {"files": files, "links": links}


def dumps(manifest):
    return json.dumps(manifest, indent=2, sort_keys=True, ensure_ascii=False) + "\n"


def _inside(root, rel):
    """The path under root that the manifest's rel names, or ManifestMismatch if rel isn't a plain relative path
    that stays inside root (the manifest comes from the backup, so it's as untrusted as the rest of it)."""
    try:
        clean = clean_name(rel)
    except UnsafeArchive:
        raise ManifestMismatch(f"{rel!r} isn't a path inside the backup") from None
    path = os.path.join(root, *clean.split("/"))
    folder = os.path.realpath(os.path.dirname(path))
    if not is_within(os.path.realpath(root), folder):
        raise ManifestMismatch(f"{rel} isn't a path inside the backup")
    return path


def verify(root, manifest):
    """ManifestMismatch unless every file and link the manifest lists is under root as it says."""
    if not isinstance(manifest, dict):
        raise ManifestMismatch("the manifest isn't an object")
    files, links = manifest.get("files", {}), manifest.get("links", {})
    if not isinstance(files, dict) or not isinstance(links, dict):
        raise ManifestMismatch("the manifest's files and links must be objects")
    for rel, digest in files.items():
        path = _inside(root, rel)
        if os.path.islink(path) or not os.path.isfile(path):
            raise ManifestMismatch(f"{rel} is missing")
        if sha256(path) != digest:
            raise ManifestMismatch(f"{rel} doesn't match its checksum")
    for rel, target in links.items():
        path = _inside(root, rel)
        if not os.path.islink(path) or os.readlink(path) != target:
            raise ManifestMismatch(f"{rel} should link to {target}")

files.plugins/installer.py:
"""Installing and removing plugin bundles. A bundle is a tar archive with plugin.json at its root."""
import json
import os
import shutil
import tarfile

from archive import UnsafeArchive, safe_extract, write_marker

from . import manifest

MARKER = ".installed"


class BundleRejected(Exception):
    """The bundle can't be installed; nothing was installed."""


def read_manifest(bundle_path):
    try:
        with tarfile.open(bundle_path) as tar:
            try:
                member = tar.getmember("plugin.json")
            except KeyError:
                raise BundleRejected("the bundle has no plugin.json at its root") from None
            if not member.isfile():
                raise BundleRejected("plugin.json isn't a regular file")
            with tar.extractfile(member) as f:
                return manifest.parse(f.read(64 * 1024))
    except (tarfile.TarError, OSError) as e:
        raise BundleRejected(f"not a readable tar archive: {e}") from None
    except manifest.ManifestError as e:
        raise BundleRejected(str(e)) from None


def install_bundle(bundle_path, plugins_dir):
    """Install the bundle into plugins_dir/<its name> and return its Manifest. BundleRejected when the bundle is
    malformed, unsafe or already installed; plugins_dir is left as it was then."""
    found = read_manifest(bundle_path)
    dest = os.path.join(plugins_dir, found.name)
    if os.path.lexists(dest):
        raise BundleRejected(f"{found.name} is already installed")
    os.mkdir(dest)
    try:
        names = safe_extract(bundle_path, dest)
    except UnsafeArchive as e:
        os.rmdir(dest)  # safe_extract wrote nothing, so the folder is still empty
        raise BundleRejected(f"{found.name}: {e}") from None
    except BaseException:
        shutil.rmtree(dest)
        raise
    try:
        if found.entry not in names:
            raise BundleRejected(f"{found.name}: its entry {found.entry} isn't in the bundle")
        write_marker(os.path.join(dest, MARKER),
                     json.dumps({"name": found.name, "version": found.version, "members": len(names)}))
    except BaseException:
        shutil.rmtree(dest)
        raise
    return found


def uninstall(plugins_dir, name):
    if not manifest.NAME.fullmatch(name):
        raise KeyError(name)  # not a plugin name, so not a folder to delete
    dest = os.path.join(plugins_dir, name)
    if not os.path.isfile(os.path.join(dest, MARKER)):
        raise KeyError(name)
    shutil.rmtree(dest)

files.shop/cache/changes.py:
"""What a unit of work changed, as the cache needs to know it.

A change names a sku, the facets of it that changed (product, price, stock) and any tags its write touches beyond
them, such as the category listings a renamed or moved product shows up in. A unit keeps one change per sku, so a
unit that writes a sku many times still costs the cache one entry for it.
"""
from dataclasses import dataclass, replace

from . import keys

FACETS = ("product", "price", "stock")


@dataclass(frozen=True)
class Change:
    sku: str
    facets: frozenset
    extra_tags: frozenset = frozenset()
    seq: int = 0

    def __post_init__(self):
        unknown = set(self.facets) - set(FACETS)
        if unknown:
            raise ValueError(f"unknown facets {sorted(unknown)}")
        if not self.facets:
            raise ValueError("a change names at least one facet")

    def tags(self):
        return {keys.tag(facet, self.sku) for facet in self.facets} | set(self.extra_tags)

    def merge(self, later):
        """This change followed by a later one to the same sku: everything either of them touched. The later write
        is not the only one that matters, since an earlier write's facets (say, the price) may not be touched again."""
        return Change(self.sku, self.facets | later.facets, self.extra_tags | later.extra_tags,
                      seq=max(self.seq, later.seq))


class ChangeSet:
    def __init__(self):
        self._by_sku = {}
        self._seq = 0

    def add(self, change):
        self._seq += 1
        change = replace(change, seq=self._seq)
        held = self._by_sku.get(change.sku)
        self._by_sku[change.sku] = change if held is None else held.merge(change)

    def get(self, sku):
        return self._by_sku.get(sku)

    def tags(self):
        """Every tag the unit's changes touch, sorted."""
        found = set()
        for change in self._by_sku.values():
            found |= change.tags()
        return sorted(found)

    def skus(self):
        return sorted(self._by_sku)

    def __len__(self):
        return len(self._by_sku)

"""What a unit of work changed, as the cache needs to know it.

A change names a sku, the facets of it that changed (product, price, stock) and any tags its write touches beyond
them, such as the category listings a renamed or moved product shows up in. A unit keeps one change per sku, so a
unit that writes a sku many times still costs the cache one entry for it.
"""
from dataclasses import dataclass, replace

from . import keys

FACETS = ("product", "price", "stock")


@dataclass(frozen=True)
class Change:
    sku: str
    facets: frozenset
    extra_tags: frozenset = frozenset()
    seq: int = 0

    def __post_init__(self):
        unknown = set(self.facets) - set(FACETS)
        if unknown:
            raise ValueError(f"unknown facets {sorted(unknown)}")
        if not self.facets:
            raise ValueError("a change names at least one facet")

    def tags(self):
        return {keys.tag(facet, self.sku) for facet in self.facets} | set(self.extra_tags)

    def merge(self, later):
        """This change followed by a later one to the same sku. The later write holds the state that commits, but
        every facet and tag either write touched must still be dropped: a price written before a rename still has
        a cached price to drop."""
        return replace(later,
                       facets=frozenset(self.facets) | frozenset(later.facets),
                       extra_tags=frozenset(self.extra_tags) | frozenset(later.extra_tags),
                       seq=max(self.seq, later.seq))


class ChangeSet:
    def __init__(self):
        self._by_sku = {}
        self._seq = 0

    def add(self, change):
        self._seq += 1
        change = replace(change, seq=self._seq)
        held = self._by_sku.get(change.sku)
        self._by_sku[change.sku] = change if held is None else held.merge(change)

    def get(self, sku):
        return self._by_sku.get(sku)

    def tags(self):
        """Every tag the unit's changes touch, sorted."""
        found = set()
        for change in self._by_sku.values():
            found |= change.tags()
        return sorted(found)

    def skus(self):
        return sorted(self._by_sku)

    def __len__(self):
        return len(self._by_sku)
